/// <summary>
/// CB503_CustomerNumbering
/// Extension of CustGroup METEnableCustNumbering field
/// </summary>
[ExtensionOf(formDataFieldStr(CustGroup, CustGroup, METEnableCustNumbering))]
internal final class METCustGroup_EnableCustNumbering_extension
{
}

Method.Source:
    /// <summary>
    /// custom logic on Modified method
    /// </summary>
    public void modified()
    {
        FormDataObject  formDataObject = any2Object(this) as FormDataObject;
        CustGroup       custGroup;

        next modified();
        custGroup = formDataObject.datasource().cursor();
        formDataObject.datasource().object(fieldNum(CustGroup, CustAccountNumSeq)).allowEdit(custGroup.METEnableCustNumbering);
        if (custGroup.METEnableCustNumbering == NoYes::No)
        {
            custGroup.CustAccountNumSeq = 0;
        }
    }
